const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={applications:'Vehicle approvals',users:'Accounts',vehicles:'Vehicles',rides:'Ride offers',bookings:'Bookings & payments',incidents:'Safety reports',allocations:'Tree allocations',heat:'Heat studies',audit:'Audit history'};
export function mountOperator(root){
 let token='',kind='applications',offset=0,records=[],more=false,search='',busy=false,epoch=0;
 root.innerHTML=`<details class="panel operator-panel"><summary><strong>Operator dashboard</strong> · Owner access</summary><p>Manage approvals, vehicles, journeys and evidence records. Separate operator sign-in is required.</p><p role="status" class="operator-status"></p><div class="operator-body"></div></details>`;
 const body=root.querySelector('.operator-body'),status=root.querySelector('.operator-status');
 const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;
 const reference=()=>field('reference','Verification / case reference (no identity-document numbers)','','text','minlength="3" maxlength="200"');
 const select=(name,label,values,value)=>`<label>${label}<select name="${name}">${values.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`;
 const check=(name,label,on=false)=>`<label class="check-row"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;
 function login(){body.innerHTML=`<form data-op-form="login"><h3>Operator sign in</h3>${field('email','Email','','email','autocomplete="username"')}${field('password','Password','','password','autocomplete="current-password" maxlength="128"')}<button class="button dark">Sign in as operator</button></form><p class="form-note">Operator sessions expire after one hour and are kept only in memory. Closing or reloading the app signs you out.</p>`;}
 function clear(){epoch++;token='';records=[];login();}
 async function request(path,method='GET',data){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);
  try{const r=await fetch((window.PLANTO_CONFIG?.apiUrl||'')+'/v1/operator'+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal,cache:'no-store'});const result=await r.json();if(!r.ok){if(r.status===401&&token)clear();throw Error(typeof result.detail==='string'?result.detail:'Check the form values.');}return result;}catch(e){if(e.name==='AbortError')throw Error('The service took too long. Refresh the records before trying the action again.');throw e;}finally{clearTimeout(timer);}
 }
 async function run(fn){if(busy)return;busy=true;status.textContent='Working…';try{await fn();}catch(e){status.textContent=e.message;}finally{busy=false;}}
 function dashboard(){body.innerHTML=`<div class="trip-actions"><button class="button outline" data-op="logout">Operator sign out</button><button class="button outline" data-op="refresh">Refresh records</button></div><label>Manage<select id="op-kind">${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${k===kind?'selected':''}>${l}</option>`).join('')}</select></label><form data-op-form="search">${field('query','Search name/phone for accounts, plate/phone for vehicles, ID/reference otherwise',search,'search').replace(' required','')}<button class="button outline">Search</button></form><div class="operator-records"></div><div class="trip-actions"><button class="button outline" data-op="previous" ${offset===0?'disabled':''}>Previous</button><span>Page ${offset/50+1}</span><button class="button outline" data-op="next" ${!more?'disabled':''}>Next</button></div><div class="operator-editor"></div>`;
  body.querySelector('.operator-records').innerHTML=records.length?`<div class="operator-table"><table><thead><tr>${Object.keys(records[0]).map(k=>`<th>${esc(k.replaceAll('_',' '))}</th>`).join('')}<th>Action</th></tr></thead><tbody>${records.map((r,i)=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}<td>${['applications','users','vehicles','incidents'].includes(kind)?`<button class="button outline button-small" data-op="edit" data-index="${i}">${kind==='incidents'?'Review':'Manage'}</button>`:kind==='rides'&&r.status==='open'?`<button class="button outline button-small" data-op="edit" data-index="${i}">Close offer</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p>No matching records.</p>';
  if(['vehicles','allocations','heat'].includes(kind))body.querySelector('.operator-editor').innerHTML=`<button class="button dark" data-op="new">${kind==='vehicles'?'Approve vehicle':kind==='allocations'?'Record tree allocation':'Record heat study'}</button>`;
 }
 async function load(){const version=epoch;const r=await request('/records/'+kind+'?'+new URLSearchParams({q:search,offset}));if(version!==epoch)return;records=r.records;more=r.has_more;dashboard();status.textContent='Records loaded. Changes require a reference and confirmation.';}
 async function edit(r={}){
  const box=body.querySelector('.operator-editor');let fields='';
  if(kind==='applications'){
   const version=epoch;let photos;
   try{photos=await request('/vehicle-applications/'+r.id+'/documents');}catch(e){photos={images:{}};status.textContent=e.message;}
   if(version!==epoch)return;
   fields=`<p>${esc(r.name)} · ${esc(r.phone)} · ${esc(r.plate)} · ${esc(r.vehicle)} · ${esc(r.status)}</p><p>Government verification is not connected. Photos alone do not establish authenticity. Check licence validity, identity, vehicle registration, insurance and eligibility using your approved process. Approve the Driver account under Accounts before approving this vehicle.</p>${Object.entries(photos.images).map(([k,v])=>`<figure><figcaption>${esc(k==='licence'?'Driving licence':'Masked Aadhaar')}</figcaption><img style="max-width:100%;max-height:420px;object-fit:contain" alt="Private ${esc(k)} photo" src="${esc(v)}"></figure>`).join('')}${select('decision','Decision',[['approved','Approve'],['rejected','Reject']], 'rejected')}${check('documents_reviewed','I reviewed both documents and completed eligibility checks.')}<label>Review note (visible to driver; no document numbers)<textarea name="note" minlength="3" maxlength="1000" required></textarea></label><p>Document access is logged. Photos expire after 30 days. Record your verification reference below.</p>`;
  }
  if(kind==='users')fields=`<p><strong>${esc(r.name)}</strong> · ${esc(r.phone)}</p>${select('role','Account type',[['rider','Rider'],['driver','Driver']],r.role)}${check('approved','Identity and phone checked; approve account',!!r.approved)}${check('woman_verified','Ladies eligibility checked and verified',!!r.woman_verified)}<p>Uncheck approval to suspend. Changing access signs the person out. Keep supporting documents in your secure records.</p>`;
  if(kind==='vehicles')fields=`<p>Copy the driver Account ID from Accounts. The account must be approved and set to Driver.</p>${field('driver_id','Driver Account ID',r.driver_id)}${field('plate','Registration plate',r.plate,'text','pattern="[A-Z0-9 -]{6,16}"')}${field('vehicle','Vehicle make and model',r.vehicle)}${select('services','Approved services',[['shared,cab','Shared and Car'],['shared','Shared only'],['cab','Car only'],['bike','Bike only']],r.services==='cab,shared'?'shared,cab':r.services||'shared,cab')}${select('operation','Action',[['approve','Approve / update'],['revoke','Revoke approval']], 'approve')}<p>Confirm licence, registration, insurance and service eligibility before approving. Revoking closes new offers; existing bookings are retained.</p>`;
  if(kind==='rides')fields=`<p>Close offer ${esc(r.id)}? New bookings stop. Existing bookings are retained; this does not cancel a passenger’s trip.</p>`;
  if(kind==='incidents')fields=`<p>${esc(r.detail)}</p>${select('status','Review status',[['open','Open'],['reviewing','Under review'],['resolved','Resolved']],r.review_status)}<label>Review note<textarea name="note" minlength="3" maxlength="2000" required>${esc(r.review_note)}</textarea></label><p>This records your review; it does not call emergency services or notify the passenger.</p>`;
  if(kind==='allocations')fields=`<p>Only completed, paid bookings qualify. Entries are published in impact reporting and must have evidence. Do not enter forecasts as actual contributions.</p>${field('booking_id','Booking ID')}${field('rider_inr','Rider allocation (INR)','0','number','min="0" step="0.01"')}${field('owner_inr','Owner allocation (INR)','0','number','min="0" step="0.01"')}${field('trees','Recorded trees','0','number','min="0" step="1"')}${field('evidence_url','Public evidence URL','','url')}`;
  if(kind==='heat')fields=`<p>Record a measured local study, with a comparison site and matched samples. No carbon-to-temperature conversion is used. These records become public.</p>${field('site','Public study site')}${field('before_at','Before date/time with timezone (ISO, e.g. 2026-01-01T12:00:00+05:30)')}${field('after_at','After date/time with timezone (ISO)')}${['site_before','site_after','control_before','control_after'].map(k=>field(k,k.replaceAll('_',' ')+' mean temperature °C','','number','min="-60" max="80" step="any"')).join('')}${field('samples','Matched samples per period','','number','min="2" step="1"')}<label>Measurement protocol and weather controls<textarea name="protocol" minlength="30" maxlength="2000" required></textarea></label>${field('evidence_url','Public evidence URL','','url')}`;
  box.innerHTML=`<form data-op-form="edit" data-record="${esc(r.id||'')}"><h3>${labels[kind]}</h3>${fields}${reference()}<button class="button dark">Review and save</button><button type="button" class="button outline" data-op="refresh">Cancel</button></form>`;box.scrollIntoView({block:'start',behavior:'smooth'});
 }
 root.addEventListener('change',e=>{if(e.target.id==='op-kind'){if(busy){e.target.value=kind;return;}kind=e.target.value;offset=0;search='';void run(load);}});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-op]');if(!b)return;void run(async()=>{const a=b.dataset.op;if(a==='logout'){await request('/session','DELETE');clear();status.textContent='Operator signed out.';return;}if(a==='edit'){await edit(records[Number(b.dataset.index)]);status.textContent='Review the details below.';return;}if(a==='new'){edit();status.textContent='Complete the evidence fields below.';return;}if(a==='previous')offset=Math.max(0,offset-50);if(a==='next')offset+=50;await load();});});
 root.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.opForm)return;e.preventDefault();void run(async()=>{const data=Object.fromEntries(new FormData(form));if(form.dataset.opForm==='login'){const r=await request('/login','POST',data);token=r.token;epoch++;form.reset();await load();return;}if(form.dataset.opForm==='search'){search=data.query;offset=0;await load();return;}if(!window.confirm('Save this operator action? Confirm you checked the details and supporting evidence.')){status.textContent='No changes saved.';return;}let path,method='POST',payload=data;
  if(kind==='applications'){path='/vehicle-applications/'+form.dataset.record+'/review';payload={decision:data.decision,reference:data.reference,note:data.note,documents_reviewed:data.documents_reviewed==='on'};}
  if(kind==='users'){path='/users/'+form.dataset.record;method='PATCH';payload={role:data.role,approved:data.approved==='on',woman_verified:data.woman_verified==='on',reference:data.reference};}
  if(kind==='vehicles'){path=data.operation==='revoke'?'/vehicles/revoke':'/vehicles';payload={driver_id:data.driver_id,plate:data.plate,vehicle:data.vehicle,services:data.services.split(','),reference:data.reference};}
  if(kind==='incidents'){path='/incidents/'+form.dataset.record;method='PATCH';}
  if(kind==='rides')path='/rides/'+form.dataset.record+'/close';
  if(kind==='allocations'){path='/allocations';payload.trees=Number(data.trees);}
  if(kind==='heat'){path='/heat';for(const k of ['samples','site_before','site_after','control_before','control_after'])payload[k]=Number(data[k]);}
  await request(path,method,payload);await load();status.textContent='Saved successfully. Account changes require the user to sign in again.';
 });});
 login();
}
